import { useReducedMotion } from "../hooks/use-media-query";

type SurfaceId = "web" | "tui" | "cli";

interface SurfaceClip {
  id: SurfaceId;
  label: string;
  eyebrow: string;
  title: string;
  description: string;
  handoff: string;
  src: string;
  poster: string;
}

const SURFACES: SurfaceClip[] = [
  {
    id: "web",
    label: "Web",
    eyebrow: "01 // LEARN",
    title: "Ask in the classroom.",
    description:
      "A live Gemini session: the learner asks why cities form where they do. Keating reasons in the open, then hands back the one question worth answering next.",
    handoff: "Move to the TUI when reading turns into working.",
    src: "/tapes/web-classroom.mp4",
    poster: "/tapes/posters/web-classroom.jpg",
  },
  {
    id: "tui",
    label: "TUI",
    eyebrow: "02 // COLLABORATE",
    title: "Keep the dialogue in your terminal.",
    description:
      "The collaborative OpenTUI host runs the same conversation through Pi — plans, concept maps, and everything Keating knows about you stay one keystroke away.",
    handoff: "Drop to the CLI when the conversation should leave something behind.",
    src: "/tapes/tui-collaborative.mp4",
    poster: "/tapes/posters/tui-collaborative.jpg",
  },
  {
    id: "cli",
    label: "CLI",
    eyebrow: "03 // INSPECT",
    title: "Turn the lesson into files.",
    description:
      "One Special Relativity session becomes a plan, a concept map, a verification checklist, and a full trace — generated live by the Bun CLI, not staged for the camera.",
    handoff: "Head back to the web shell when it is time to teach it back.",
    src: "/tapes/cli-artifacts.mp4",
    poster: "/tapes/posters/cli-artifacts.jpg",
  },
];

interface ProductRoute {
  label: string;
  detail: string;
  to: "/chat" | "/live" | "/coming-up" | "/courses" | "/blog";
}

const PRODUCT_ROUTES: ProductRoute[] = [
  {
    label: "Classroom",
    detail: "Ask, explain, and inspect the reasoning",
    to: "/chat",
  },
  {
    label: "Live",
    detail: "Bring voice, camera, and tools into the lesson",
    to: "/live",
  },
  {
    label: "Coming Up",
    detail: "Return to what is due or still uncertain",
    to: "/coming-up",
  },
  {
    label: "Courses",
    detail: "Keep lessons, sources, notes, and decks together",
    to: "/courses",
  },
  {
    label: "Publication",
    detail: "Read the release record and field work",
    to: "/blog",
  },
];

export function SurfaceScreencasts() {
  const reducedMotion = useReducedMotion();
  const [activeId, setActiveId] = useState<SurfaceId>("web");
  const [autoplayBlocked, setAutoplayBlocked] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const activeIndex = SURFACES.findIndex((surface) => surface.id === activeId);
  const active = SURFACES[activeIndex];

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    let cancelled = false;
    const stopPlayback = () => {
      cancelled = true;
      video.pause();
    };
    setAutoplayBlocked(false);
    video.currentTime = 0;
    if (reducedMotion) {
      video.pause();
      return stopPlayback;
    }
    void video.play().catch(() => {
      if (!cancelled) setAutoplayBlocked(true);
    });
    return stopPlayback;
  }, [activeId, reducedMotion]);

  function handleTabKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    let nextIndex = activeIndex;
    if (event.key === "ArrowRight" || event.key === "ArrowDown") {
      nextIndex = (activeIndex + 1) % SURFACES.length;
    } else if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
      nextIndex = (activeIndex - 1 + SURFACES.length) % SURFACES.length;
    } else if (event.key === "Home") {
      nextIndex = 0;
    } else if (event.key === "End") {
      nextIndex = SURFACES.length - 1;
    } else {
      return;
    }

    event.preventDefault();
    setActiveId(SURFACES[nextIndex].id);
    tabRefs.current[nextIndex]?.focus();
  }

  return (
    <section
      id="watch"
      className={css({
        position: "relative",
        overflow: "hidden",
        borderBlock: "2px solid var(--ink)",
        background:
          "radial-gradient(circle at 92% 8%, rgba(75, 227, 136, 0.14), transparent 24rem), var(--terminal)",
        color: "#dcefe0",
        paddingBlock: { base: "4.5rem", md: "7rem" },
      })}
      aria-labelledby="surface-screencasts-title"
    >
      <div
        className={css({
          width: "min(1180px, calc(100% - 2rem))",
          marginInline: "auto",
        })}
      >
        <div
          className={css({
            display: "grid",
            gap: { base: "1.25rem", md: "3rem" },
            alignItems: "end",
            gridTemplateColumns: { base: "1fr", md: "minmax(0, 1fr) minmax(17rem, 0.55fr)" },
          })}
        >
          <div>
            <div className={sectionHead()}>
              <span className={cx("eyebrow", "prompt", css({ color: "var(--phosphor)" }))}>
                open SURFACES.mp4
              </span>
            </div>
            <h2
              id="surface-screencasts-title"
              className={cx(sectionTitle(), css({ maxWidth: "13ch", color: "var(--paper)" }))}
            >
              One question, three surfaces.
            </h2>
          </div>
          <p
            className={cx(
              sectionLede(),
              css({
                margin: 0,
                maxWidth: "36rem",
                color: "rgba(220, 239, 224, 0.72)",
              }),
            )}
          >
            These are real sessions recorded against the product. Start in the browser, continue in
            the terminal, then inspect the files Keating leaves behind.
          </p>
        </div>

        <div
          className={css({
            display: "grid",
            gap: { base: "1.5rem", lg: "2.75rem" },
            alignItems: "start",
            marginTop: { base: "2.5rem", md: "4rem" },
            gridTemplateColumns: { base: "minmax(0, 1fr)", lg: "18rem minmax(0, 1fr)" },
          })}
        >
          <div>
            <div
              role="tablist"
              aria-label="Choose a Keating surface"
              className={css({
                display: "flex",
                overflowX: "auto",
                gap: { base: "0.65rem", lg: "0.75rem" },
                flexDirection: { base: "row", lg: "column" },
              })}
            >
              {SURFACES.map((surface, index) => {
                const selected = surface.id === activeId;
                return (
                  <button
                    key={surface.id}
                    ref={(node) => {
                      tabRefs.current[index] = node;
                    }}
                    type="button"
                    id={`surface-tab-${surface.id}`}
                    role="tab"
                    aria-selected={selected}
                    aria-controls={`surface-panel-${surface.id}`}
                    tabIndex={selected ? 0 : -1}
                    onClick={() => setActiveId(surface.id)}
                    onKeyDown={handleTabKeyDown}
                    className={css({
                      position: "relative",
                      flex: { base: "0 0 auto", lg: "initial" },
                      minWidth: { base: "7rem", lg: "100%" },
                      border: selected
                        ? "2px solid var(--phosphor)"
                        : "1px solid rgba(220, 239, 224, 0.34)",
                      background: selected ? "var(--phosphor)" : "transparent",
                      color: selected ? "var(--terminal)" : "#dcefe0",
                      padding: { base: "0.85rem 1rem", lg: "1rem 1.25rem" },
                      textAlign: "left",
                      fontFamily: "var(--font-mono)",
                      fontSize: "0.8rem",
                      fontWeight: 800,
                      letterSpacing: "0.08em",
                      textTransform: "uppercase",
                      cursor: "pointer",
                      transition:
                        "background-color 160ms ease, border-color 160ms ease, color 160ms ease",
                      _hover: {
                        borderColor: "var(--phosphor)",
                        background: selected ? "var(--phosphor)" : "rgba(75, 227, 136, 0.08)",
                      },
                      _focusVisible: {
                        outline: "3px solid var(--amber)",
                        outlineOffset: "3px",
                        zIndex: 1,
                      },
                    })}
                  >
                    <span
                      className={css({
                        display: { base: "none", lg: "inline" },
                        marginRight: "0.65rem",
                        color: selected ? "var(--terminal)" : "var(--phosphor-dim)",
                      })}
                    >
                      0{index + 1}
                    </span>
                    {surface.label}
                  </button>
                );
              })}
            </div>

            <p
              className={css({
                display: { base: "none", lg: "block" },
                marginTop: "1.75rem",
                borderTop: "1px solid rgba(220, 239, 224, 0.3)",
                paddingTop: "1.25rem",
                color: "var(--phosphor-dim)",
                fontFamily: "var(--font-mono)",
                fontSize: "0.72rem",
                lineHeight: 1.65,
              })}
            >
              WEB → TUI → CLI → WEB
              <br />
              One project. Three entry points.
            </p>
          </div>

          <div className={css({ minWidth: 0 })}>
            {SURFACES.filter((surface) => surface.id !== active.id).map((surface) => (
              <div
                key={surface.id}
                id={`surface-panel-${surface.id}`}
                role="tabpanel"
                aria-labelledby={`surface-tab-${surface.id}`}
                hidden
              />
            ))}
          <div
            id={`surface-panel-${active.id}`}
            role="tabpanel"
            aria-labelledby={`surface-tab-${active.id}`}
            tabIndex={0}
            className={css({
              minWidth: 0,
              _focusVisible: { outline: "3px solid var(--amber)", outlineOffset: "5px" },
            })}
          >
            <div
              className={css({
                position: "relative",
                overflow: "hidden",
                border: "2px solid rgba(220, 239, 224, 0.84)",
                background: "#070b08",
                boxShadow: {
                  base: "5px 5px 0 rgba(75, 227, 136, 0.56)",
                  md: "9px 9px 0 rgba(75, 227, 136, 0.56)",
                },
                aspectRatio: "16 / 9",
              })}
            >
              <video
                key={active.id}
                ref={videoRef}
                className={css({ display: "block", width: "100%", height: "100%", objectFit: "cover" })}
                src={active.src}
                poster={active.poster}
                muted
                loop
                playsInline
                controls
                autoPlay={!reducedMotion}
                preload="metadata"
                aria-label={`${active.label} screencast: ${active.title}`}
              >
                Your browser does not support embedded video.
              </video>
              <div
                className={css({
                  position: "absolute",
                  top: "0.8rem",
                  left: "0.8rem",
                  border: "1px solid rgba(220, 239, 224, 0.7)",
                  background: "rgba(7, 11, 8, 0.88)",
                  color: "var(--phosphor)",
                  padding: "0.35rem 0.55rem",
                  fontFamily: "var(--font-mono)",
                  fontSize: { base: "0.58rem", md: "0.68rem" },
                  fontWeight: 800,
                  letterSpacing: "0.08em",
                  pointerEvents: "none",
                })}
                aria-hidden="true"
              >
                {active.eyebrow}
              </div>

